// Read a button and a knob, and print both.
const int BUTTON_PIN = 2;   // Button to GND, no resistor needed
const int SENSOR_PIN = A0;  // Knob wiper

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LED_BUILTIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  bool pressed = digitalRead(BUTTON_PIN) == LOW;  // INPUT_PULLUP: pressed reads LOW
  digitalWrite(LED_BUILTIN, pressed ? HIGH : LOW);

  int raw = analogRead(SENSOR_PIN);  // 0..1023
  float volts = raw * (5.0 / 1023.0);
  Serial.print("A0=");
  Serial.print(raw);
  Serial.print(" (");
  Serial.print(volts, 2);
  Serial.print(" V) D2=");
  Serial.println(pressed ? "LOW" : "HIGH");
  delay({{p:period}});
}

