// Read a button and a knob, and print both.
const int BUTTON_PIN = 2;   // Button to GND, no resistor needed
const int SENSOR_PIN = A0;  // Knob wiper

void setup() {
  pinMode(BUTTON_PIN, INPUT_PULLUP);
  pinMode(LED_BUILTIN, OUTPUT);
  Serial.begin(9600);
}

void loop() {
